import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService, Korisnik } from "../../services/auth.service";

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  public imagePath: string = 'assets/administar.jpg';
  public registerForm: FormGroup;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private authService: AuthService
  ) {
    this.registerForm = this.fb.group({
      ime: ['', Validators.required],
      prezime: ['', Validators.required],
      email: [
        '',
        [
          Validators.required,
          Validators.email,
          Validators.pattern(/^[a-zA-Z0-9._%+-]+@gmail\.com$/) // samo gmail.com
        ]
      ],
      lozinka: [
        '',
        [
          Validators.required,
          Validators.minLength(8),
          Validators.pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\W).{8,}$/) // veliko, malo, specijalan znak
        ]
      ],
      rola: ['CITIZEN', Validators.required]
    });
  }

  public goToLogin(): void {
    this.router.navigate(['/login']);
  }

  public onSubmit(): void {
    if (this.registerForm.valid) {
      const korisnikData: Korisnik = this.registerForm.value;

      this.authService.register(korisnikData).subscribe({
        next: (response) => {
          console.log('Uspešna registracija:', response);
          alert('Registracija uspešna! Možete se prijaviti.');
          this.router.navigate(['/login']);
        },
        error: (error) => {
          console.error('Greška pri registraciji:', error);
          alert(error.error || 'Došlo je do greške pri registraciji.');
        }
      });

    } else {
      alert('Molimo popunite sva obavezna polja ispravno.\n' +
        '- Email mora biti u formatu @gmail.com\n' +
        '- Lozinka mora imati min. 8 karaktera, veliko slovo, malo slovo i specijalan znak.');
    }
  }
}
<section class="vh-100 signup-section">
  <div class="container h-100">
    <div class="row d-flex justify-content-center align-items-center h-100">
      <div class="col-lg-12 col-xl-11">
        <div class="card signup-card">
          <div class="row g-0 h-100">

            <!-- Forma levo -->
            <div class="col-md-6 d-flex justify-content-center align-items-center">
              <div class="p-4 p-md-5 form-container-padding w-100">
                <p class="text-center h1 fw-bold mb-4">Sign up</p>
                <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">

                  <div class="mb-4">
                    <label for="ime" class="form-label">First name</label>
                    <input id="ime" type="text" class="form-control" formControlName="ime" placeholder="Enter your first name">
                  </div>

                  <div class="mb-4">
                    <label for="prezime" class="form-label">Last name</label>
                    <input id="prezime" type="text" class="form-control" formControlName="prezime" placeholder="Enter your last name">
                  </div>

                  <div class="mb-4">
                    <label for="email" class="form-label">Email</label>
                    <input id="email" type="email" class="form-control" formControlName="email" placeholder="Enter your email">
                  </div>

                  <div class="mb-4">
                    <label for="lozinka" class="form-label">Password</label>
                    <input id="lozinka" type="password" class="form-control" formControlName="lozinka" placeholder="Enter your password">
                  </div>

                  <button type="submit" class="btn btn-dark w-100">Register</button>

                  <p class="text-center mt-3">
                    Already have an account?
                    <a href="#" class="login-link" (click)="goToLogin()">Login here</a>
                  </p>
                </form>
              </div>
            </div>

            <!-- Slika desno -->
            <div class="col-md-6 d-none d-md-block">
              <img [src]="imagePath" alt="Signup image" class="signup-image">
            </div>

          </div>
        </div>
      </div>
    </div>
  </div>
</section>
